    # first boundary vertex by id), then propagate.
    q = deque()
    for w in range(n):
        if in_sub[w]:
            continue
        if dist[w] == -1:
            continue
        for x in adj[w]:
            if in_sub[x]:
                cand = dist[w] + 1
                if dist[x] == -1 or cand < dist[x]:
                    dist[x] = cand
                    parent[x] = w
    for x in subtree:
        if dist[x] != -1:
            q.append(x)
    while q:
        x = q.popleft()
        dx = dist[x]
        for y in adj[x]:
            if dist[y] == -1 or dx + 1 < dist[y]:
                dist[y] = dx + 1
                parent[y] = x
                q.append(y)
